async function fetch_data(frm){
    const emps = await frappe.db.get_list("Employee", 
        {
            fields:["name","employee_name","company","department","user_id","designation", "is_manager"],
            filters:[
            ],
            limit:0
        }
    );

    const leave_type = await frappe.db.get_doc("Leave Type", frm.doc.leave_type);
    const leave_period = await frappe.db.get_doc("Leave Period", frm.doc.leave_period);


    const prev_leaves = await frappe.db.get_list("Leave Allocation", 
        {
            fields:["*"],
            filters:[
                ["to_date","<",leave_period.from_date],
            ],
            limit:0
        }
    );

    const leaves = await frappe.db.get_list("Attendance", 
        {
            fields:["*"],
            filters:[
                ["status","=", "On Leave"],
                ["attendance_date","<", leave_period.from_date],
            ],
            limit:0
        }
    );

    frm.doc.leaves_list = [];

    for(let e of emps){
        const emp_alloc_leaves = prev_leaves.filter(x => x.employee == e.name);
        let unused_leaves = 0;
        for(let alloc of emp_alloc_leaves)
        {
            const found_leaves = leaves.filter(x => x.employee == e.name && x.attendance_date >= alloc.from_date && x.attendance_date <= alloc.to_date);

            unused_leaves += alloc.new_leaves_allocated - found_leaves.length;

        }

        console.log(e.employee_name, unused_leaves);
        frm.add_child("leaves_list", {
            doctype: "Auto Leave Allocation Table",
            employee: e.name,
            employee_name: e.employee_name,
            unused_leaves: unused_leaves,
            new_leaves: unused_leaves + frm.doc.new_leaves
        });
    }

    frm.refresh_field("leaves_list");
    console.log(emps);
}

